(function() {
'use strict';
var _res=[], _queue=[], _selId=null, _files=[];
function fs(b){if(!b)return '未知';var u=['B','KB','MB','GB'];var i=0,s=b;while(s>=1024&&i<u.length-1){s/=1024;i++;}return s.toFixed(1)+' '+u[i];}
function fd(n){if(!n)return '—';return n>=1e6?(n/1e6).toFixed(1)+'M':n>=1e3?(n/1e3).toFixed(1)+'K':n;}
function toast(m,t){var c=document.getElementById('toastContainer');if(!c)return;var e=document.createElement('div');e.className='toast toast-'+(t||'info');e.textContent=m;c.appendChild(e);setTimeout(function(){e.classList.add('show');},10);setTimeout(function(){e.classList.remove('show');setTimeout(function(){e.remove();},300);},3000);}
async function openM(){try{await window.__TAURI__.core.invoke('open_hf_store_window');await loadS();}catch(e){console.error(e);toast('打开商城失败: '+e,'error');}}
async function loadS(){try{var t=await window.__TAURI__.core.invoke('get_hf_token');var ti=document.getElementById('hfTokenInput');if(ti&&t)ti.value='********';var d=await window.__TAURI__.core.invoke('get_hf_download_dir');var di=document.getElementById('hfDownloadDirInput');if(di)d.value=d;}catch(e){console.error(e);}}
async function search(q){if(!q||!q.trim())return;document.getElementById('hfEmptyState').style.display='none';var ls=document.getElementById('hfLoadingState');ls.removeAttribute('hidden');document.getElementById('hfModelsContainer').innerHTML='';document.getElementById('hfDetailPanel').setAttribute('hidden','');var to=setTimeout(function(){document.getElementById('hfModelsContainer').innerHTML='<p style="color:var(--danger);padding:20px;text-align:center;">搜索超时（网络过慢或被限流），请稍后重试或设置 HF Token</p>';ls.setAttribute('hidden','');},35000);try{var r=await window.__TAURI__.core.invoke('search_hf_models',{query:q.trim(),limit:30});clearTimeout(to);_res=r;renderR(r);}catch(e){clearTimeout(to);console.error(e);document.getElementById('hfModelsContainer').innerHTML='<p style="color:var(--danger);padding:20px;text-align:center;">搜索失败: '+e+'</p>';}finally{clearTimeout(to);ls.setAttribute('hidden','');}}
function renderR(models){var c=document.getElementById('hfModelsContainer');if(!models||!models.length){c.innerHTML='<p style="color:var(--text-3);padding:20px;text-align:center;">未找到相关模型</p>';return;}var html='';for(var i=0;i<models.length;i++){var m=models[i];var tags='';for(var j=0;j<m.tags.length&&j<4;j++){tags+='<span class="hf-model-tag">'+m.tags[j]+'</span>';}html+='<div class="hf-model-card" data-v="'+m.id+'">'+'<div class="hf-model-card-header"><div class="hf-model-id">'+m.id.split('/').slice(1).join('/')+'</div></div><div class="hf-model-statsch(34)><span>\u2193 '+fd(m.downloads)+'</span><span>\u2665 '+fd(m.likes)+'</span></div>'+(m.description?'<div class="hf-model-desc">'+m.description+'</div>':'')+'<div class="hf-model-tags">'+tags+'</div></div>';}c.innerHTML=html;c.querySelectorAll('[data-v]').forEach(function(b){b.addEventListener('click',function(){if(b.hasAttribute('disabled'))return;viewF(b.dataset.v);});});}
async function viewF(mid){_selId=mid;document.getElementById('hfDetailModelId').textContent=mid;document.getElementById('hfDetailBody').innerHTML='<div style="display:flex;align-items:center;gap:12px;padding:40px;"><div class="spinner"></div><p>正在获取模型文件列表...</p></div>';var dp=document.getElementById('hfDetailPanel');if(dp)dp.removeAttribute('hidden');try{var f=await window.__TAURI__.core.invoke('get_hf_model_files',{modelId:mid});_files=f;renderF(mid,f);}catch(e){console.error(e);document.getElementById('hfDetailBody').innerHTML='<p style="color:var(--danger);padding:20px;">加载失败: '+e+'</p>';}}
function renderF(mid,files){var b=document.getElementById('hfDetailBody');if(!files||!files.length){b.innerHTML='<p style="color:var(--text-3);padding:20px;">该模型暂无文件</p>';return;}var html='';for(var i=0;i<files.length;i++){var f=files[i];var dl='hf-dl-'+mid.replace(/[^a-z0-9]/gi,'-')+'-'+f.path.replace(/[^a-z0-9]/gi,'-').replace(/[.]/g,'_');var sz=f.size||f.file_size||0;html+='<div class="hf-model-file-row" data-d="'+dl+'"><div class="hf-file-name" title="'+f.path+'">'+f.path.split('/').pop()+'</div><div class="hf-file-size">'+fs(sz)+'</div><div class="hf-dl-actions"><button class="btn-primary" data-dl="'+dl+'" style="padding:3px 10px;font-size:11px;">下载</button></div></div>';}b.innerHTML=html;b.querySelectorAll('[data-dl]').forEach(function(btn){btn.addEventListener('click',function(){var dl=this.getAttribute('data-dl');var row=this.closest('[data-d]');if(row)row.classList.add('hf-dl-queued');var id=row.dataset.d;var fi=files.find(function(fi2){return 'hf-dl-'+mid.replace(/[^a-z0-9]/gi,'-')+'-'+fi2.path.replace(/[^a-z0-9]/gi,'-').replace(/[.]/g,'_')===id;});if(fi){startD(mid,fi.path.split('/').pop(),fi.size||fi.file_size||0);}});});}
async function startD(mid,fn,sz){var dl='hf-dl-'+mid.replace(/[^a-z0-9]/gi,'-')+'-'+fn.replace(/[^a-z0-9]/gi,'-');var it={id:dl,mid:mid,fn:fn,sz:sz||0,st:'downloading',p:0,dl:0,tl:0,sp:0,et:0,path:''};_queue.push(it);renderDl(it);updateDc();var panel=document.getElementById('hfDownloadsPanel');if(panel&&panel.dataset.open!=='1')toggleDlPanel();(async function(){try{var r=await window.__TAURI__.core.invoke('download_hf_model',{modelId:mid,filename:fn,installDir:null});it.st='complete';it.p=1;it.dl=it.tl||(r.file_size||0);it.path=r.path;renderDl(it);updateDc();toast('下载完成: '+fn,'success');setTimeout(function(){removeDl(it.id);},4000);}catch(e){console.error(e);it.st='error';renderDl(it);updateDc();toast('下载失败: '+e,'error');setTimeout(function(){removeDl(it.id);},6000);}})();}
function removeDl(id){_queue=_queue.filter(function(d){return d.id!==id;});var el=document.getElementById(id);if(el)el.remove();updateDc();updateEmptyDl();}
function updateDc(){var c=document.getElementById('hfDownloadsCount');var n=_queue.filter(function(d){return d.st==='downloading';}).length;if(c)c.textContent=n;showDlBadge(n);}
function updateEmptyDl(){var el=document.getElementById('hfEmptyDl');if(el)el.style.display=_queue.length===0?'block':'none';}
function showDlBadge(n){var b=document.getElementById('hfDlBadge');if(b){b.textContent=n;b.style.display=n>0?'flex':'none';}}
function toggleDlPanel(){var p=document.getElementById('hfDownloadsPanel');if(!p)return;var isOpen=p.dataset.open==='1';if(isOpen){p.style.opacity='0';p.style.transform='translateY(12px)';p.style.pointerEvents='none';p.dataset.open='0';}else{p.style.opacity='1';p.style.transform='translateY(0)';p.style.pointerEvents='auto';p.dataset.open='1';}}
function renderDl(it){var el=document.getElementById(it.id);var st=it.st, pg=Math.min(100,Math.round((it.p||0)*100));var dlSize=(it.dl||0), tlSize=(it.tl||0);var sp=(it.sp||0);var fn=it.fn.split('/').pop();var sizeStr=tlSize>0?(fs(dlSize)+' / '+fs(tlSize)):(it.sz?fs(it.sz):'未知');var speedStr=(st==='downloading'&&sp>0)?(' '+fs(sp)+'/s'):'';var etaStr=(st==='downloading'&&it.et>0&&sp>0)?(' · '+formatEta(it.et)):'';var icon=st==='complete'?'&#x2714;':st==='error'?'&#x2716;':st==='downloading'?'&#x25B6;':'&#x23F8;';var col=st==='complete'?'var(--success,#4caf50)':st==='error'?'var(--danger,#f44336)':st==='downloading'?'var(--accent,#6c8ef5)':'var(--text-3)';var barCol=st==='complete'?'var(--success,#4caf50)':st==='error'?'var(--danger,#f44336)':'var(--accent,#6c8ef5)';var label=st==='complete'?'完成':st==='error'?'失败':st==='downloading'?pg+'%':'等待';var html='<div style="display:flex;align-items:center;gap:10px;width:100%;"><span style="font-size:12px;color:'+col+';min-width:16px;text-align:center;">'+icon+'</span><div style="flex:1;display:flex;flex-direction:column;gap:5px;min-width:0;"><div style="display:flex;align-items:center;gap:6px;"><div style="flex:1;height:4px;background:var(--bg-3,#e5e7eb);border-radius:2px;overflow:hidden;"><div style="height:100%;width:'+pg+'%;background:'+barCol+';border-radius:2px;transition:width .2s ease;"></div></div><span style="font-size:11px;font-weight:600;color:'+col+';min-width:38px;text-align:right;">'+label+'</span></div><div style="font-size:10px;color:var(--text-2,#6b7280);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">'+fn+'</div><div style="font-size:10px;color:var(--text-3,#9ca3af);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">'+sizeStr+speedStr+etaStr+'</div></div><button onclick="removeDl(it.id)"" title="移除" style="flex-shrink:0;background:none;border:none;color:var(--text-3);cursor:pointer;font-size:14px;padding:4px 6px;border-radius:4px;line-height:1;opacity:.5;transition:opacity .15s;min-width:24px;">&#x2715;</button></div>';if(el){el.innerHTML=html;el.dataset.status=st;}else{var d=document.createElement('div');d.id=it.id;d.dataset.status=st;d.style.cssText='background:var(--bg-2,#f9fafb);border:1px solid var(--border,#e5e7eb);border-radius:8px;padding:10px;display:flex;align-items:center;gap:10px;min-height:56px;';d.innerHTML=html;var list=document.getElementById('hfDownloadsList');if(list)list.appendChild(d);}var empty=document.getElementById('hfEmptyDl');if(empty)empty.style.display='none';if(_selId)renderF(_selId,_files);}
function formatEta(secs){if(secs<60)return Math.round(secs)+'秒';if(secs<3600)return Math.floor(secs/60)+'分'+Math.round(secs%60)+'秒';return Math.floor(secs/3600)+'时'+Math.floor((secs%3600)/60)+'分';}
function init(){if(!document.getElementById('hfDownloadsPanel')){var fp=document.createElement('div');fp.id='hfDownloadsPanel';fp.dataset.open='0';fp.style.cssText='position:fixed;bottom:84px;right:24px;width:340px;max-height:440px;background:var(--bg-1);border:1px solid var(--border);border-radius:12px;box-shadow:0 8px 28px rgba(0,0,0,0.22);display:flex;flex-direction:column;z-index:998;overflow:hidden;opacity:0;transform:translateY(12px);transition:opacity .18s ease,transform .18s ease;pointer-events:none;';fp.innerHTML='<div style="display:flex;justify-content:space-between;align-items:center;padding:10px 14px;border-bottom:1px solid var(--border);flex-shrink:0;background:var(--bg-2);"><div style="display:flex;align-items:center;gap:6px;font-weight:600;font-size:13px;color:var(--text-1);"><span>\u2B07</span><span>下载队列</span></div><div style="display:flex;align-items:center;gap:8px;"><span id="hfDownloadsCount" style="font-size:11px;color:var(--text-3);background:var(--bg-3);padding:1px 7px;border-radius:8px;">0</span><button id="hfCloseDlBtn" title="关闭" style="background:none;border:none;cursor:pointer;color:var(--text-3);font-size:16px;line-height:1;padding:2px 6px;border-radius:4px;">x</button></div></div><div id="hfDownloadsList" style="flex:1;overflow-y:auto;padding:8px;display:flex;flex-direction:column;gap:6px;min-height:60px;"><p id="hfEmptyDl" style="text-align:center;color:var(--text-3);font-size:12px;padding:24px 0;margin:0;">暂无下载任务</p></div>';document.body.appendChild(fp);document.getElementById('hfCloseDlBtn').addEventListener('click',toggleDlPanel);var fab=document.getElementById('hfDlFab');if(fab)fab.addEventListener('click',toggleDlPanel);}var inStore=!!document.getElementById('hfResultsList');if(inStore){loadS();}var ob=document.getElementById('openHfStoreBtn');if(ob)ob.addEventListener('click',openM);var si=document.getElementById('hfSearchInput');if(si)si.addEventListener('keydown',function(e){if(e.key==='Enter')search(si.value);});var sb=document.getElementById('hfSearchBtn');if(sb)sb.addEventListener('click',function(){search(document.getElementById('hfSearchInput').value);});var bb=document.getElementById('hfBackBtn');if(bb)bb.addEventListener('click',function(){var dp=document.getElementById('hfDetailPanel');dp.setAttribute('hidden','');dp.style.display='';});var ts=document.getElementById('hfTokenSaveBtn');if(ts)ts.addEventListener('click',async function(){var t=document.getElementById('hfTokenInput').value.trim();if(!t){toast('请输入Token','warning');return;}try{await window.__TAURI__.core.invoke('set_hf_token',{token:t});document.getElementById('hfTokenInput').value='********';toast('Token已保存','success');}catch(e){toast('保存失败','error');}});var ds=document.getElementById('hfDownloadDirSaveBtn');if(ds)ds.addEventListener('click',async function(){var d=document.getElementById('hfDownloadDirInput').value.trim();if(!d){toast('请输入目录','warning');return;}try{await window.__TAURI__.core.invoke('set_hf_download_dir',{dir:d});toast('目录已保存','success');}catch(e){toast('保存失败','error');}});window.__TAURI__.event.listen('hf-download-progress',function(ev){var p=ev.payload;var dl='hf-dl-'+p.model_id.replace(/[^a-z0-9]/gi,'-')+'-'+p.filename.replace(/[^a-z0-9]/gi,'-');var it=_queue.find(function(d){return d.id===dl;});if(it){it.st=p.stage==='complete'?'complete':p.stage==='error'?'error':'downloading';it.p=Math.min(1,(p.progress||0));it.dl=p.downloaded||0;it.tl=p.total||0;it.sp=p.speed||0;it.et=p.eta||0;if(p.message)it.msg=p.message;renderDl(it);}else if(p.stage==='init'){var nit={id:dl,mid:p.model_id,fn:p.filename,sz:0,st:'downloading',p:0,dl:0,tl:0,sp:0,et:0,msg:p.message||'',path:''};_queue.push(nit);renderDl(nit);updateDc();}});}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();
})();
